package com.example.pokemonsavemanager

import android.util.Base64
import java.io.InputStream

data class LegendsArceusMoveShopOffering(
    val index: Int,
    val moveId: Int,
    val moveName: String,
    val purchased: Boolean,
    val mastered: Boolean
) {
    override fun toString(): String =
        "$moveName (#$moveId) • ${if (purchased) "purchased" else "not purchased"} • " +
            if (mastered) "mastered" else "not mastered"
}

data class LegendsArceusPokemonMoveShopValues(
    val pokemon: LegendsArceusPokemonRead,
    val offerings: List<LegendsArceusMoveShopOffering>
)

/** Purchases one species/form-permitted native PLA move-shop move and reviews its mastery flag. */
object LegendsArceusPokemonMoveShopEditing {
    private const val STORED_END = 0x168
    private const val PURCHASED_FLAGS = 0x155
    private const val MASTERED_FLAGS = 0x15D
    private const val BLOCK_SIZE = 88
    private const val SPECIES_COUNT = 906
    private const val ENTRY_COUNT = 1276
    private const val META_SIZE = SPECIES_COUNT * 3
    private const val PACKED_SIZE = META_SIZE + ENTRY_COUNT * 8
    private val orders = listOf("0123", "0132", "0213", "0312", "0231", "0321",
        "1023", "1032", "2013", "3012", "2031", "3021", "1203", "1302",
        "2103", "3102", "2301", "3201", "1230", "1320", "2130", "3120", "2310", "3210")
    private val moveIds = intArrayOf(
        206, 424, 422, 423, 301, 249, 191, 523, 332, 446, 129, 161, 345, 466,
        829, 116, 339, 347, 156, 608, 7, 9, 8, 409, 398, 427, 428, 141, 404, 157,
        421, 442, 231, 595, 352, 451, 412, 196, 188, 414, 247, 555, 430, 605, 416,
        401, 528, 667, 224, 444, 200, 583, 63, 53, 85, 58, 94, 399, 434, 796, 344
    )
    private val packed: ByteArray by lazy {
        Base64.decode(PACKED, Base64.NO_WRAP).also {
            require(it.size == PACKED_SIZE) { "The pinned Legends: Arceus move-shop permit table is incomplete." }
        }
    }

    fun readDocumentBytes(input: InputStream): ByteArray =
        LegendsArceusPokemonNicknameEditing.readDocumentBytes(input)

    fun sha256(bytes: ByteArray): String = LegendsArceusPokemonNicknameEditing.sha256(bytes)

    fun read(
        source: ByteArray,
        area: LegendsArceusPokemonArea,
        pasture: Int,
        position: Int
    ): LegendsArceusPokemonMoveShopValues {
        val blocks = LegendsArceusSaveValidation.readPokemonBlocks(source)
        return inspect(targetRecord(blocks, area, pasture, position))
    }

    fun stage(
        source: ByteArray,
        expectedSha256: String,
        area: LegendsArceusPokemonArea,
        pasture: Int,
        position: Int,
        requestedIndex: Int,
        requestedMastered: Boolean
    ): LegendsArceusPokemonMoveShopCopyPlan {
        val original = source.copyOf()
        require(sha256(original) == expectedSha256) { "The source changed. Reopen it from PSE." }
        val blocks = LegendsArceusSaveValidation.readPokemonBlocks(original)
        val beforeRecord = targetRecord(blocks, area, pasture, position)
        val before = inspect(beforeRecord)
        require(!before.pokemon.isEgg) { "Egg PA8 records remain protected from move-shop editing." }
        require(!before.pokemon.isNoble) { "Noble PA8 records remain protected from move-shop editing." }
        val selected = before.offerings.singleOrNull { it.index == requestedIndex }
            ?: throw IllegalArgumentException(
                "That move is not permitted by this PA8 species/form's pinned native move-shop table."
            )
        require(!selected.purchased || selected.mastered != requestedMastered) {
            "Choose a different purchase or mastery state before review."
        }
        val afterRecord = editRecord(beforeRecord, requestedIndex, requestedMastered)
        val written = if (area == LegendsArceusPokemonArea.PASTURE) {
            LegendsArceusSaveValidation.writePastureRecord(original, pasture, position, afterRecord)
        } else LegendsArceusSaveValidation.writePartyRecord(original, position, afterRecord)
        val after = verify(
            original, written.bytes, area, pasture, position, written.absoluteOffset,
            requestedIndex, requestedMastered
        )
        return LegendsArceusPokemonMoveShopCopyPlan(
            original, written.bytes, area, pasture, position, written.absoluteOffset,
            requestedIndex, before, after
        )
    }

    internal fun verify(
        original: ByteArray,
        edited: ByteArray,
        area: LegendsArceusPokemonArea,
        pasture: Int,
        position: Int,
        absoluteOffset: Int,
        requestedIndex: Int,
        requestedMastered: Boolean
    ): LegendsArceusPokemonMoveShopValues {
        val beforeBlocks = LegendsArceusSaveValidation.readPokemonBlocks(original)
        val afterBlocks = LegendsArceusSaveValidation.readPokemonBlocks(edited)
        require(beforeBlocks.version == afterBlocks.version && original.size == edited.size) {
            "The move-shop edit changed native title identity or save size."
        }
        val beforeRecord = targetRecord(beforeBlocks, area, pasture, position)
        val afterRecord = targetRecord(afterBlocks, area, pasture, position)
        val before = inspect(beforeRecord)
        val after = inspect(afterRecord)
        require(after.pokemon == before.pokemon && after.offerings.size == before.offerings.size) {
            "The persisted PA8 changed outside its move-shop flags."
        }
        val beforeSelected = before.offerings.singleOrNull { it.index == requestedIndex }
            ?: error("The reviewed move-shop offering is no longer permitted.")
        val afterSelected = after.offerings.singleOrNull { it.index == requestedIndex }
            ?: error("The persisted move-shop offering is no longer permitted.")
        require(afterSelected.purchased && afterSelected.mastered == requestedMastered &&
            afterSelected.copy(purchased = beforeSelected.purchased, mastered = beforeSelected.mastered) == beforeSelected) {
            "The persisted move-shop flags do not match the reviewed purchase and mastery state."
        }
        require(before.offerings.indices.all { index ->
            before.offerings[index].index == requestedIndex || before.offerings[index] == after.offerings[index]
        }) { "Another permitted move-shop offering changed." }

        val recordSize = recordSize(area)
        val relativeOffset = if (area == LegendsArceusPokemonArea.PASTURE)
            ((pasture - 1) * 30 + position - 1) * recordSize else (position - 1) * recordSize
        val beforeTarget = if (area == LegendsArceusPokemonArea.PASTURE) beforeBlocks.pastures else beforeBlocks.party
        val afterTarget = if (area == LegendsArceusPokemonArea.PASTURE) afterBlocks.pastures else afterBlocks.party
        val beforeOther = if (area == LegendsArceusPokemonArea.PASTURE) beforeBlocks.party else beforeBlocks.pastures
        val afterOther = if (area == LegendsArceusPokemonArea.PASTURE) afterBlocks.party else afterBlocks.pastures
        require(beforeOther.contentEquals(afterOther)) { "The unselected native Pokémon storage object changed." }
        require(beforeTarget.indices.all { index ->
            index in relativeOffset until relativeOffset + recordSize || beforeTarget[index] == afterTarget[index]
        }) { "Another native Pokémon slot changed." }

        val beforePlain = decryptAndUnshuffle(beforeRecord)
        val afterPlain = decryptAndUnshuffle(afterRecord)
        val purchasedOffset = PURCHASED_FLAGS + requestedIndex / 8
        val masteredOffset = MASTERED_FLAGS + requestedIndex / 8
        val mask = 1 shl (requestedIndex and 7)
        val expectedPurchasedByte = byte(beforePlain, purchasedOffset) or mask
        val expectedMasteredByte = if (requestedMastered)
            byte(beforePlain, masteredOffset) or mask
        else byte(beforePlain, masteredOffset) and mask.inv()
        require(flag(afterPlain, PURCHASED_FLAGS, requestedIndex) &&
            flag(afterPlain, MASTERED_FLAGS, requestedIndex) == requestedMastered &&
            byte(afterPlain, purchasedOffset) == expectedPurchasedByte &&
            byte(afterPlain, masteredOffset) == expectedMasteredByte) {
            "The native move-shop flags were not changed exactly."
        }
        require(beforePlain.indices.all { offset ->
            offset in 6..7 || offset == purchasedOffset || offset == masteredOffset ||
                beforePlain[offset] == afterPlain[offset]
        }) { "The PA8 edit exceeded one Purchased flag, one Mastered flag and checksum fields." }

        val hashOffset = original.size - 32
        require(original.indices.all { index ->
            index in absoluteOffset until absoluteOffset + recordSize ||
                index in hashOffset until original.size || original[index] == edited[index]
        }) { "An unrelated encrypted container byte changed." }
        return after
    }

    private fun inspect(record: ByteArray): LegendsArceusPokemonMoveShopValues {
        val pokemon = (LegendsArceusPokemonReadOnly.read(record) as? LegendsArceusSlotRead.Pokemon)?.value
            ?: throw IllegalArgumentException("The selected native PA8 is not checksum-valid.")
        val plain = decryptAndUnshuffle(record)
        val permit = permitMask(pokemon.species, pokemon.form)
        val offerings = moveIds.indices.filter { permit and (1L shl it) != 0L }.map { index ->
            val choice = LegendsArceusMoveCatalog.choice(moveIds[index])
                ?: error("The pinned move-shop move #${moveIds[index]} is unavailable.")
            LegendsArceusMoveShopOffering(
                index, choice.id, choice.name,
                flag(plain, PURCHASED_FLAGS, index),
                flag(plain, MASTERED_FLAGS, index)
            )
        }
        return LegendsArceusPokemonMoveShopValues(pokemon, offerings)
    }

    private fun permitMask(species: Int, form: Int): Long {
        require(species in 1..905) { "The PA8 species has no pinned Legends: Arceus move-shop profile." }
        val meta = species * 3
        val formIndex = byte(packed, meta) or (byte(packed, meta + 1) shl 8)
        val formCount = byte(packed, meta + 2)
        val entry = if (form == 0) species else {
            require(formIndex > 0 && form in 1 until formCount) {
                "The PA8 form has no pinned Legends: Arceus move-shop profile."
            }
            formIndex + form - 1
        }
        require(entry in 0 until ENTRY_COUNT) { "The PA8 move-shop profile index is outside the pinned table." }
        val offset = META_SIZE + entry * 8
        var result = 0L
        for (index in 0..7) result = result or (byte(packed, offset + index).toLong() shl (index * 8))
        return result
    }

    private fun targetRecord(
        blocks: LegendsArceusPokemonBlocks,
        area: LegendsArceusPokemonArea,
        pasture: Int,
        position: Int
    ): ByteArray {
        val size = recordSize(area)
        if (area == LegendsArceusPokemonArea.PASTURE) {
            require(pasture in 1..32 && position in 1..30) { "The selected native pasture slot is outside storage." }
            val offset = ((pasture - 1) * 30 + position - 1) * size
            return blocks.pastures.copyOfRange(offset, offset + size)
        }
        require(position in 1..6) { "The selected native party slot is outside the six-slot party." }
        val count = blocks.party[6 * size].toInt() and 255
        require(position <= count) { "The selected native party slot is not occupied." }
        val offset = (position - 1) * size
        return blocks.party.copyOfRange(offset, offset + size)
    }

    private fun recordSize(area: LegendsArceusPokemonArea): Int =
        if (area == LegendsArceusPokemonArea.PASTURE) LegendsArceusPokemonReadOnly.STORED_SIZE
        else LegendsArceusPokemonReadOnly.PARTY_SIZE

    private fun editRecord(record: ByteArray, index: Int, mastered: Boolean): ByteArray {
        val plain = decryptAndUnshuffle(record)
        setFlag(plain, PURCHASED_FLAGS, index, true)
        setFlag(plain, MASTERED_FLAGS, index, mastered)
        var checksum = 0
        for (offset in 8 until STORED_END step 2) checksum += u16(plain, offset)
        writeU16(plain, 6, checksum and 0xFFFF)
        return shuffleAndEncrypt(plain)
    }

    private fun flag(bytes: ByteArray, base: Int, index: Int): Boolean =
        byte(bytes, base + index / 8) and (1 shl (index and 7)) != 0

    private fun setFlag(bytes: ByteArray, base: Int, index: Int, value: Boolean) {
        val offset = base + index / 8
        val mask = 1 shl (index and 7)
        val current = byte(bytes, offset)
        bytes[offset] = (if (value) current or mask else current and mask.inv()).toByte()
    }

    private fun decryptAndUnshuffle(record: ByteArray): ByteArray {
        require(record.size == LegendsArceusPokemonReadOnly.STORED_SIZE ||
            record.size == LegendsArceusPokemonReadOnly.PARTY_SIZE) {
            "Expected one complete native stored or party PA8 record."
        }
        val ec = u32(record, 0)
        val decoded = record.copyOf()
        xorWords(decoded, 8, STORED_END, ec)
        if (record.size == LegendsArceusPokemonReadOnly.PARTY_SIZE)
            xorWords(decoded, STORED_END, LegendsArceusPokemonReadOnly.PARTY_SIZE, ec)
        val order = orders[((ec ushr 13).toInt() and 31) % 24]
        val plain = decoded.copyOf()
        for (block in 0..3) {
            val from = 8 + (order[block] - '0') * BLOCK_SIZE
            decoded.copyInto(plain, 8 + block * BLOCK_SIZE, from, from + BLOCK_SIZE)
        }
        return plain
    }

    private fun shuffleAndEncrypt(plain: ByteArray): ByteArray {
        val ec = u32(plain, 0)
        val order = orders[((ec ushr 13).toInt() and 31) % 24]
        val shuffled = plain.copyOf()
        for (block in 0..3) {
            val destination = 8 + (order[block] - '0') * BLOCK_SIZE
            plain.copyInto(shuffled, destination, 8 + block * BLOCK_SIZE, 8 + (block + 1) * BLOCK_SIZE)
        }
        xorWords(shuffled, 8, STORED_END, ec)
        if (plain.size == LegendsArceusPokemonReadOnly.PARTY_SIZE)
            xorWords(shuffled, STORED_END, LegendsArceusPokemonReadOnly.PARTY_SIZE, ec)
        return shuffled
    }

    private fun xorWords(bytes: ByteArray, from: Int, end: Int, seed: Long) {
        var state = seed
        for (offset in from until end step 2) {
            state = (state * 0x41C64E6DL + 0x6073L) and 0xFFFFFFFFL
            writeU16(bytes, offset, u16(bytes, offset) xor (state ushr 16).toInt())
        }
    }

    private fun byte(bytes: ByteArray, offset: Int): Int = bytes[offset].toInt() and 255
    private fun u16(bytes: ByteArray, offset: Int): Int = byte(bytes, offset) or (byte(bytes, offset + 1) shl 8)
    private fun u32(bytes: ByteArray, offset: Int): Long =
        u16(bytes, offset).toLong() or (u16(bytes, offset + 2).toLong() shl 16)
    private fun writeU16(bytes: ByteArray, offset: Int, value: Int) {
        bytes[offset] = value.toByte(); bytes[offset + 1] = (value ushr 8).toByte()
    }

    private const val PACKED = ""
}

class LegendsArceusPokemonMoveShopCopyPlan internal constructor(
    original: ByteArray,
    edited: ByteArray,
    val area: LegendsArceusPokemonArea,
    val pasture: Int,
    val position: Int,
    val absoluteOffset: Int,
    val selectedIndex: Int,
    val before: LegendsArceusPokemonMoveShopValues,
    val after: LegendsArceusPokemonMoveShopValues
) {
    private val original = original.copyOf()
    private val edited = edited.copyOf()
    val editedSha256: String = LegendsArceusPokemonMoveShopEditing.sha256(this.edited)
    private var consumed = false

    val beforeSelected: LegendsArceusMoveShopOffering
        get() = before.offerings.single { it.index == selectedIndex }
    val afterSelected: LegendsArceusMoveShopOffering
        get() = after.offerings.single { it.index == selectedIndex }

    @Synchronized
    fun saveNewCopy(
        readSource: () -> ByteArray,
        retainBackup: (ByteArray) -> ByteArray,
        readDestination: () -> ByteArray,
        writeDestination: (ByteArray) -> Unit,
        discardDestination: () -> Boolean
    ) {
        check(!consumed) { "This move-shop review was already used. Reopen Pokémon Details." }
        consumed = true
        fun requireSource() = require(readSource().contentEquals(original)) {
            "The selected source changed. Reopen it from PSE."
        }
        requireSource()
        require(readDestination().isEmpty()) { "Choose a new empty document; existing files cannot be replaced." }
        require(retainBackup(original.copyOf()).contentEquals(original)) {
            "The recovery backup did not verify. Nothing was written."
        }
        requireSource()
        require(readDestination().isEmpty()) { "The destination changed. Nothing was written." }
        var started = false
        try {
            LegendsArceusPokemonMoveShopEditing.verify(
                original, edited, area, pasture, position, absoluteOffset,
                selectedIndex, afterSelected.mastered
            )
            started = true
            writeDestination(edited.copyOf())
            val persisted = readDestination()
            require(persisted.contentEquals(edited)) { "The saved copy differs from the reviewed move-shop edit." }
            LegendsArceusPokemonMoveShopEditing.verify(
                original, persisted, area, pasture, position, absoluteOffset,
                selectedIndex, afterSelected.mastered
            )
            requireSource()
        } catch (failure: Exception) {
            val removed = started && runCatching { discardDestination() }.getOrDefault(false)
            throw IllegalStateException(
                (failure.message ?: "Move-shop copy verification failed.") +
                    if (removed) " The failed new copy was removed; the recovery backup is retained."
                    else " The new copy could not be removed. Do not use it; the recovery backup is retained.",
                failure
            )
        }
    }
}
